  const lang = localStorage.getItem('appLanguage') || 'en';

  if (state.certifications.length === 0) {
    list.innerHTML = `<div class="empty-state"><i class="fas fa-certificate"></i><p>${t('noCertifications', lang)}</p></div>`;
