  function parseCSVLine(line) {
    const values = [];
    let current = '';
    let inQuotes = false;

    for (let i = 0; i < line.length; i++) {
      const char = line[i];

      if (char === '"') {
        inQuotes = !inQuotes;
      } else if (char === ',' && !inQuotes) {
        values.push(current.trim());
        current = '';
      } else {
        current += char;
      }
    }
    values.push(current.trim());

    return values.map(v => v.replace(/^"|"$/g, ''));
  }

  function parseDate(dateStr) {
    if (!dateStr) return new Date().toISOString().split('T')[0];

    dateStr = dateStr.replace(/"/g, '').trim();

    if (dateStr.includes('/')) {
      const parts = dateStr.split('/');
      if (parts.length === 3) {
        let year = parts[2] || parts[0];
        let month = parts[0];
        let day = parts[1];

        if (dateStr.match(/^\d{4}/)) {
          year = parts[0];
          month = parts[1];
          day = parts[2];
        }

        if (year.length === 2) year = '20' + year;
        return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
      }
    }

    return dateStr;
  }

  function parsePhotoUrls(photoStr) {
    if (!photoStr) return [];

    const photos = [];
    const parts = photoStr.split(',').map(p => p.trim());

    for (const part of parts) {
      if (part.includes('drive.google.com')) {
        const match = part.match(/id=([a-zA-Z0-9_-]+)/);
        if (match) {
          photos.push(`https://drive.google.com/thumbnail?id=${match[1]}&sz=w800`);
        }
      } else if (part.match(/\.(jpg|jpeg|png|gif)$/i)) {
        photos.push(`/uploads/${part}`);
      } else if (part.length > 5) {
        photos.push(part);
      }
    }

    return photos;
  }

