}

.eom-info {
  display: flex;
  flex-direction: column;
}

.eom-label {
  font-size: 11px;
  opacity: 0.9;
  text-transform: uppercase;
  font-weight: 600;
}

.eom-name {
  font-size: 18px;
  font-weight: 700;
}

.eom-points {
  font-size: 14px;
  opacity: 0.9;
  display: flex;
  align-items: center;
  gap: 4px;
}

/* KPI Grid Extension */
.kpi-grid {
  grid-template-columns: repeat(4, 1fr);
}

.kpi-danger .kpi-icon { background: rgba(239,68,68,0.15); color: var(--danger); }

@media (max-width: 480px) {
  .kpi-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* Challenges */
.challenges-card .section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.view-all {
  color: var(--primary);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
}

.challenges-mini-list {
  padding: 8px;
}

.challenge-mini-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  background: var(--bg-input);
  border-radius: var(--radius-sm);
  margin-bottom: 8px;
  cursor: pointer;
  transition: all 0.2s;
}

.challenge-mini-item:hover {
  background: var(--border);
}

.challenge-mini-item.completed {
  opacity: 0.6;
}

.challenge-mini-item.completed .challenge-icon {
  background: var(--success);
  color: white;
}

.challenge-icon {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--primary);
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
}

.challenge-info {
  flex: 1;
}

.challenge-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
}

.challenge-points {
  font-size: 12px;
  color: #fbbf24;
  font-weight: 600;
}

.challenge-status {
  font-size: 20px;
  color: var(--success);
}

/* Leaderboard */
.leaderboard-mini {
  padding: 8px;
}

.leaderboard-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  background: var(--bg-input);
  border-radius: var(--radius-sm);
  margin-bottom: 8px;
}

.leaderboard-rank {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 14px;
}

.leaderboard-rank.gold { background: linear-gradient(135deg, #fbbf24 0%, #f59e0b 100%); color: white; }
.leaderboard-rank.silver { background: linear-gradient(135deg, #94a3b8 0%, #cbd5e1 100%); color: white; }
.leaderboard-rank.bronze { background: linear-gradient(135deg, #b45309 0%, #d97706 100%); color: white; }
.leaderboard-rank.default { background: var(--bg-card); color: var(--text-secondary); border: 1px solid var(--border); }

.leaderboard-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--primary);
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  font-weight: 600;
}

.leaderboard-info {
  flex: 1;
}

.leaderboard-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
}

.leaderboard-area {
  font-size: 12px;
  color: var(--text-secondary);
}

.leaderboard-points {
  font-size: 16px;
  font-weight: 700;
  color: #fbbf24;
  display: flex;
  align-items: center;
  gap: 4px;
}

.leaderboard-tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}

.leaderboard-tab {
  flex: 1;
  padding: 12px;
  background: var(--bg-input);
  border: none;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.2s;
}

.leaderboard-tab.active {
  background: var(--primary);
  color: white;
}

.leaderboard-full .leaderboard-item {
  background: var(--bg-card);
  border: 1px solid var(--border);
}

/* Challenges Full List */
.challenges-intro {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  border-radius: var(--radius-md);
  padding: 20px;
  margin-bottom: 16px;
  color: white;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.challenges-progress {
  font-size: 18px;
  font-weight: 700;
}

.challenges-points {
  font-size: 14px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.challenges-list .challenge-card {
  background: var(--bg-card);
  border-radius: var(--radius-md);
  padding: 16px;
  margin-bottom: 12px;
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  gap: 16px;
  cursor: pointer;
  transition: all 0.2s;
}

.challenges-list .challenge-card:hover {
  box-shadow: var(--shadow-md);
}

.challenges-list .challenge-card.completed {
  background: rgba(16,185,129,0.1);
  border-color: var(--success);
}

.challenge-card .challenge-icon {
  width: 50px;
  height: 50px;
  font-size: 20px;
}

.challenge-card .challenge-info h3 {
