/* Alerts */
.alerts-list {
  padding: 8px;
}

.alert-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  background: rgba(239,68,68,0.1);
  border-radius: var(--radius-sm);
  margin-bottom: 8px;
  border-left: 3px solid var(--danger);
