.badge-popup {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0,0,0,0.8);
  z-index: 2000;
  display: flex;
  align-items: center;
  justify-content: center;
  animation: fadeIn 0.3s ease;
}

.badge-popup-content {
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  padding: 40px;
  text-align: center;
  max-width: 300px;
  animation: bounceIn 0.5s ease;
}

@keyframes bounceIn {
  0% { transform: scale(0.5); opacity: 0; }
  50% { transform: scale(1.1); }
  100% { transform: scale(1); opacity: 1; }
}

.badge-popup-icon {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: linear-gradient(135deg, #fbbf24 0%, #f59e0b 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 36px;
  color: white;
  margin: 0 auto 20px;
  animation: pulse 2s infinite;
}

.badge-popup h3 {
  font-size: 24px;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 8px;
}

.badge-popup p {
  font-size: 16px;
  color: var(--text-secondary);
  margin-bottom: 24px;
}

/* Profile */
.profile-header-card {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  border-radius: var(--radius-lg);
  padding: 30px;
  text-align: center;
  color: white;
  margin-bottom: 20px;
}

.profile-avatar {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: rgba(255,255,255,0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 32px;
  margin: 0 auto 16px;
}

.profile-header-card h2 {
  font-size: 22px;
  font-weight: 700;
  margin-bottom: 4px;
}

.profile-header-card p {
  opacity: 0.9;
  font-size: 14px;
}

.profile-level {
  margin-top: 12px;
}

.profile-stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-bottom: 20px;
}

.profile-stat {
  background: var(--bg-card);
  border-radius: var(--radius-md);
  padding: 20px 16px;
  text-align: center;
  border: 1px solid var(--border);
}

.profile-stat .stat-value {
  font-size: 24px;
  font-weight: 700;
  color: var(--primary);
  display: block;
}

.profile-stat .stat-label {
  font-size: 12px;
  color: var(--text-secondary);
}

.profile-badges-section,
.profile-activity-section {
  background: var(--bg-card);
  border-radius: var(--radius-md);
  padding: 16px;
  margin-bottom: 16px;
  border: 1px solid var(--border);
}

.profile-badges-section h3,
.profile-activity-section h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 16px;
  color: var(--text-primary);
}

.badges-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.badge-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.badge-icon {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  color: white;
  margin-bottom: 8px;
}

.badge-icon.locked {
  background: var(--bg-input);
  color: var(--text-muted);
}

.badge-name {
  font-size: 11px;
  color: var(--text-secondary);
  font-weight: 500;
}

.activity-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.activity-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  background: var(--bg-input);
  border-radius: var(--radius-sm);
}

.activity-icon {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--primary);
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
}

.activity-info {
  flex: 1;
}

.activity-text {
  font-size: 13px;
  color: var(--text-primary);
}

.activity-time {
  font-size: 11px;
  color: var(--text-muted);
}

.activity-points {
  font-size: 14px;
  font-weight: 700;
  color: #fbbf24;
}

/* Notification Badge */
.notif-badge {
  position: absolute;
  top: 0;
  right: 0;
  width: 18px;
  height: 18px;
  background: var(--danger);
  color: white;
  font-size: 10px;
  font-weight: 700;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.header-btn {
  position: relative;
}

/* Modal Large */
.modal-large {
  max-width: 600px;
  max-height: 85vh;
}

/* Detail Modal */
.detail-section {
  margin-bottom: 20px;
}

.detail-section h4 {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-secondary);
  margin-bottom: 8px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.detail-section p {
  font-size: 15px;
  color: var(--text-primary);
  line-height: 1.6;
}

.detail-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.detail-item {
  background: var(--bg-input);
  padding: 12px;
  border-radius: var(--radius-sm);
}

.detail-item label {
  display: block;
  font-size: 11px;
  color: var(--text-muted);
  margin-bottom: 4px;
  text-transform: uppercase;
}

.detail-item span {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-primary);
}

.detail-photos {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.detail-photo {
  aspect-ratio: 1;
  border-radius: var(--radius-sm);
  overflow: hidden;
}

.detail-photo img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* Analytics */
.analytics-grid {
  display: grid;
  gap: 16px;
}

.analytics-card {
  background: var(--bg-card);
  border-radius: var(--radius-md);
  padding: 20px;
  border: 1px solid var(--border);
}

.analytics-card h3 {
  font-size: 16px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 16px;
}

.analytics-card canvas {
  max-height: 200px;
}

.causes-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.cause-item {
  display: flex;
  align-items: center;
  gap: 12px;
}

.cause-bar {
  flex: 1;
  height: 24px;
  background: var(--bg-input);
  border-radius: 4px;
  overflow: hidden;
  position: relative;
}

.cause-bar-fill {
  height: 100%;
  background: var(--primary);
  border-radius: 4px;
}

.cause-bar-text {
  position: absolute;
  left: 8px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 12px;
  font-weight: 500;
  color: var(--text-primary);
}

.cause-count {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-secondary);
  min-width: 40px;
  text-align: right;
}

/* Contractors Stats */
.contractors-stats {
  background: var(--bg-card);
  border-radius: var(--radius-md);
  padding: 20px;
  margin-bottom: 16px;
  border: 1px solid var(--border);
  text-align: center;
}

.contractors-stats .stat-value {
  font-size: 32px;
  font-weight: 700;
  color: var(--primary);
}

.contractors-stats .stat-label {
  font-size: 14px;
  color: var(--text-secondary);
}

/* Certification Filters */
.cert-filters {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}

.cert-filter {
  padding: 10px 20px;
  background: var(--bg-input);
  border: none;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.2s;
}

.cert-filter.active {
  background: var(--primary);
  color: white;
}

/* Card Extensions */
.card-badge {
  position: absolute;
  top: 12px;
  right: 12px;
  padding: 4px 10px;
  border-radius: var(--radius-full);
  font-size: 11px;
  font-weight: 600;
}

.card-badge.critical { background: var(--danger); color: white; }
.card-badge.major { background: #f97316; color: white; }
.card-badge.minor { background: var(--warning); color: white; }
.card-badge.near-miss { background: var(--primary); color: white; }

.card-badge.expiring { background: var(--warning); color: white; }
.card-badge.expired { background: var(--danger); color: white; }

/* Handover Card */
.handover-card {
  position: relative;
}

.handover-shift {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--text-secondary);
  margin-bottom: 8px;
}

.handover-shift i {
  color: var(--primary);
}

.handover-acknowledged {
  position: absolute;
  top: 12px;
  right: 12px;
  color: var(--success);
  font-size: 20px;
}

/* Inspection Card */
.inspection-status {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  border-radius: var(--radius-full);
  font-size: 12px;
  font-weight: 600;
}

.inspection-status.pass { background: rgba(16,185,129,0.15); color: var(--success); }
.inspection-status.fail { background: rgba(239,68,68,0.15); color: var(--danger); }
.inspection-status.partial { background: rgba(245,158,11,0.15); color: var(--warning); }

/* Admin Section */
#adminSection {
  border-top: 1px solid var(--border);
  padding-top: 20px;
  margin-top: 20px;
}

.btn-secondary {
  background: var(--bg-input);
  border: 1px solid var(--border);
  color: var(--text-primary);
  padding: 12px 20px;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: all 0.2s;
}

.btn-secondary:hover {
  background: var(--border);
}

/* Login Modal */
#loginModalOverlay {
  background: rgba(0,0,0,0.9);
}

#loginModal {
  max-width: 360px;
}

.login-register-link {
  text-align: center;
  margin-top: 16px;
  font-size: 14px;
  color: var(--text-secondary);
}

.login-register-link a {
  color: var(--primary);
  font-weight: 500;
}

.btn-block {
  width: 100%;
}

/* Photo Upload Preview */
.photo-preview-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-top: 12px;
}

.photo-preview-item {
  position: relative;
  aspect-ratio: 1;
  border-radius: var(--radius-sm);
  overflow: hidden;
}

.photo-preview-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.photo-preview-remove {
  position: absolute;
  top: 4px;
  right: 4px;
  width: 24px;
  height: 24px;
  background: var(--danger);
  color: white;
  border: none;
  border-radius: 50%;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
}

/* Weather Widget */
.weather-card {
  background: linear-gradient(135deg, #3b82f6 0%, #1d4ed8 100%);
  border-radius: var(--radius-md);
  padding: 20px;
  color: white;
  text-align: center;
}

.weather-temp {
  font-size: 48px;
  font-weight: 700;
}

.weather-desc {
  font-size: 18px;
  opacity: 0.9;
  margin-bottom: 12px;
}

.weather-details {
  display: flex;
  justify-content: center;
  gap: 24px;
  font-size: 14px;
  opacity: 0.9;
}

/* Lightbox */
.lightbox-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.95);
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
  animation: fadeIn 0.2s ease;
}

.lightbox-content {
  position: relative;
  max-width: 90vw;
  max-height: 90vh;
  display: flex;
  align-items: center;
  justify-content: center;
}

.lightbox-content img {
  max-width: 100%;
  max-height: 85vh;
  object-fit: contain;
  border-radius: 8px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
}

.lightbox-close {
  position: fixed;
  top: 20px;
  right: 20px;
  width: 44px;
  height: 44px;
  background: rgba(255, 255, 255, 0.1);
  border: none;
  border-radius: 50%;
  color: white;
  font-size: 20px;
  cursor: pointer;
  transition: all 0.2s;
  z-index: 10001;
}

.lightbox-close:hover {
  background: rgba(255, 255, 255, 0.2);
  transform: scale(1.1);
}

.lightbox-nav {
  position: fixed;
  top: 50%;
  transform: translateY(-50%);
  width: 50px;
  height: 50px;
  background: rgba(255, 255, 255, 0.1);
  border: none;
  border-radius: 50%;
  color: white;
  font-size: 20px;
  cursor: pointer;
  transition: all 0.2s;
}

.lightbox-nav:hover {
  background: rgba(255, 255, 255, 0.2);
}

.lightbox-prev { left: 20px; }
.lightbox-next { right: 20px; }

.lightbox-counter {
  position: fixed;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  color: white;
  font-size: 14px;
  background: rgba(0, 0, 0, 0.5);
  padding: 8px 16px;
  border-radius: 20px;
}

.lightbox-actions {
  position: fixed;
  bottom: 20px;
  right: 20px;
  display: flex;
  gap: 10px;
}

.lightbox-actions .btn-icon {
  background: rgba(255, 255, 255, 0.1);
  color: white;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;
}

.lightbox-actions .btn-icon:hover {
  background: rgba(255, 255, 255, 0.2);
}

/* Detail Modal Improvements */
.detail-actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
  margin-bottom: 16px;
}

.detail-actions .btn-icon {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--bg-input);
  border: 1px solid var(--border);
  color: var(--text-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
}

.detail-actions .btn-icon:hover {
  background: var(--primary);
  color: white;
  border-color: var(--primary);
}

.detail-photo {
  position: relative;
  cursor: pointer;
  border-radius: 8px;
  overflow: hidden;
  transition: transform 0.2s;
}

.detail-photo:hover {
  transform: scale(1.02);
}

.detail-photo img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.photo-overlay {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 24px;
  opacity: 0;
  transition: opacity 0.2s;
}

.detail-photo:hover .photo-overlay {
  opacity: 1;
}

.detail-photos {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
  gap: 12px;
}

.detail-photos .detail-photo {
  aspect-ratio: 4/3;
}

.detail-item label i {
  margin-right: 6px;
  color: var(--primary);
  width: 16px;
}

.detail-text {
  color: var(--text-primary);
  line-height: 1.6;
  background: var(--bg-input);
  padding: 12px;
  border-radius: var(--radius-sm);
  margin-top: 8px;
}

.status-badge {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 500;
}

.status-open, .status-badge.status-open {
  background: #fef3c7;
  color: #92400e;
}

.status-closed {
  background: #d1fae5;
  color: #065f46;
}

.status-under-investigation {
  background: #dbeafe;
  color: #1e40af;
}

/* Emergency Contacts */
.emergency-contacts-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 12px;
  margin-top: 12px;
}

.emergency-contact-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 16px;
  text-align: center;
  text-decoration: none;
  transition: all 0.2s;
}

.emergency-contact-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
  border-color: var(--primary);
}

.emergency-contact-card.emergency {
  border-left: 4px solid #ef4444;
}

.emergency-contact-card.safety {
  border-left: 4px solid #00838f;
}

.emergency-contact-card.medical {
  border-left: 4px solid #22c55e;
}

.emergency-contact-card.security {
  border-left: 4px solid #f59e0b;
}

.emergency-contact-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--primary);
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  margin: 0 auto 12px;
}

.emergency-contact-card.emergency .emergency-contact-icon {
  background: #ef4444;
}

.emergency-contact-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 4px;
}

.emergency-contact-number {
  font-size: 14px;
  font-weight: 700;
  color: var(--primary);
}

/* Professional Dashboard Styles */
.dashboard-header {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  color: white;
  padding: 24px;
  border-radius: var(--radius-lg);
  margin-bottom: 20px;
  text-align: center;
}

.dashboard-header h2 {
  margin: 0 0 8px 0;
  font-size: 24px;
}

.dashboard-header p {
  margin: 0;
  opacity: 0.9;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

.section-header h3 {
  margin: 0;
  font-size: 18px;
  font-weight: 600;
  color: var(--text-primary);
}

.section-header .view-all {
  color: var(--primary);
  font-size: 14px;
  font-weight: 500;
  text-decoration: none;
}

/* Import Button */
.import-btn {
  background: var(--success);
  color: white;
  border: none;
  padding: 10px 20px;
  border-radius: var(--radius-sm);
  font-size: 14px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: all 0.2s;
}

.import-btn:hover {
  background: #059669;
  transform: translateY(-1px);
}

.import-btn:disabled {
  background: var(--text-muted);
  cursor: not-allowed;
}

/* Library Document Cards */
.library-documents {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 16px;
}

.library-doc-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 16px;
  display: flex;
  align-items: flex-start;
  gap: 16px;
  cursor: pointer;
  transition: all 0.2s;
  text-decoration: none;
  color: inherit;
}

.library-doc-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
  border-color: var(--primary);
}

.library-doc-icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  flex-shrink: 0;
}

.library-doc-info h4 {
  margin: 0 0 4px 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--text-primary);
}

.library-doc-info p {
  margin: 0;
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.4;
}

.library-doc-badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 10px;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  margin-top: 8px;
}

.library-doc-badge.tbt { background: #dbeafe; color: #1e40af; }
.library-doc-badge.jsa { background: #fef3c7; color: #92400e; }
.library-doc-badge.csm { background: #d1fae5; color: #065f46; }
